(6604353, 985325, 60047, '<td valign="top">I love Brussels Sprouts! Looks delicious! Well composed shot.</td>', 'I love Brussels Sprouts! Looks delicious! Well composed shot.', '2011-11-27 12:26:23.000000', NULL, 1),
(6604356, 985458, 60047, '<td valign="top">I love every kind of food on this plate! I enjoy the simplicity of the meal as photographed. I think a few details would have helped this shot = straightening the silverware, not cropping off the bottom of the plate, managing the reflection under the beverage, cloning out the crumb at the 8 O''clock position near the plate and on the napkin. I also think the business of the plate detracts from the food presentation.</td>', 'I love every kind of food on this plate! I enjoy the simplicity of the meal as photographed. I think a few details would have helped this shot = straightening the silverware, not cropping off the bottom of the plate, managing the reflection under the beverage, cloning out the crumb at the 8 O''clock position near the plate and on the napkin. I also think the business of the plate detracts from the food presentation.', '2011-11-27 12:31:47.000000', NULL, 1),
(6604357, 985461, 60047, '<td valign="top">I love the deep red/orange and the darkness around it.</td>', 'I love the deep red/orange and the darkness around it.', '2011-11-27 12:32:35.000000', NULL, 1),
(6604358, 985395, 60047, '<td valign="top">I like the subject - but I am not quite comfortable with the POV of the shot.</td>', 'I like the subject - but I am not quite comfortable with the POV of the shot.', '2011-11-27 12:33:50.000000', NULL, 1),
(6604360, 985347, 60047, '<td valign="top">I love the look of the feast on the table. I think the blur vignette is a bit strong, though.</td>', 'I love the look of the feast on the table. I think the blur vignette is a bit strong, though.', '2011-11-27 12:34:53.000000', NULL, 1),
(6604362, 985451, 60047, '<td valign="top">I love the textures in the shot and the way the natural light accentuates them. Wonderful work, here.</td>', 'I love the textures in the shot and the way the natural light accentuates them. Wonderful work, here.', '2011-11-27 12:36:21.000000', NULL, 1),
(6604364, 985341, 60047, '<td valign="top">An interesting take on the challenge. Edgy and different.</td>', 'An interesting take on the challenge. Edgy and different.', '2011-11-27 12:38:14.000000', NULL, 1),
(6604365, 985418, 60047, '<td valign="top">A fun and whimsical answer to the challenge. What a great juxtaposition of the disinterested dog with the Feast!</td>', 'A fun and whimsical answer to the challenge. What a great juxtaposition of the disinterested dog with the Feast!', '2011-11-27 12:39:10.000000', NULL, 1),
(6604367, 985324, 60047, '<td valign="top">I love the subject. The lighting seems a bit harsh in the foreground. The knife doesn''t logically fit into the composition for me.</td>', 'I love the subject. The lighting seems a bit harsh in the foreground. The knife doesn''t logically fit into the composition for me.', '2011-11-27 12:40:55.000000', NULL, 1),
